1|/***
2| * MARK: harnessModelDiscovery
3| * @description Runner-side model auto-detect: one discovery leg per
4| *   supported harness (`pi`, `muse`, `antigravity`, `vibe`, `opencode`,
5| *   `codex`), each reusing its backend harness's own `listModels()` so
6| *   "ready to use right now" means the same thing on both sides of the
7| *   wire. Every leg runs best-effort behind a watchdog, caches its ids in
8| *   a per-harness slice, and keeps the previous slice on failure — a
9| *   failed scan warns, never breaks heartbeats, and never serves ids the
10| *   leg cannot back. The daemon drives one round per boot, per
11| *   `modelDiscoveryIntervalMs` tick, and per Re-detect command.
12| * @example await runDiscoveryRound({ harnessIds: ['pi', 'muse'] }) => { combinedIds: ['pi::mistral::x'], resultsByHarness: { pi: {...}, muse: {...} } }
13| ***/
14|import { harnessModelKey, parseModelKey } from "../shared/modelKeys.js";
15|import { DISCOVERY_ENV_VARS, resolveBinary } from "../api/agent/harnessDiscovery.js";
16|import { discoverClaudeModels as discoverMuseModelsRaw } from "./modelDiscovery.js";
