29|/***
30| * MARK: discoveryCache
31| * @description Per-harness discovery slices, the single place a round
32| *   reads and writes: `{ [harnessId]: { ids, atMs, error } }`. A slice
33| *   keeps its previous `ids` whenever a later round fails or empties
34| *   (survey q5), so heartbeats always advertise the last good list. Read
35| *   it through `getDiscoveryStatus()` / `summarizeDiscoverySlices()`;
36| *   reset it in tests with `clearDiscoveryCache()`.
37| * @example discoveryCache.pi => { ids: ['pi::mistral::x'], atMs: 123, error: null }
38| ***/
39|export const discoveryCache = {};
