64|/***
65| * MARK: checkFleetIdForHarness
66| * @description Whether one id is servable fleet grammar for a harness:
67| *   a canonical `harness::provider::id` (or `::reasoning`) key whose
68| *   harness segment matches. Anything else (legacy 2-part keys, bare
69| *   ids, other-harness keys, malformed text) is never advertised —
70| *   dispatch matches fleet picks verbatim, so an ungrammatical id would
71| *   match nothing and only mislead the picker.
72| * @example checkFleetIdForHarness('pi::mistral::x', 'pi') => true
73| * @example checkFleetIdForHarness('muse::meta::x', 'pi') => false
74| * @param {string} fleetId - Candidate id from a leg.
75| * @param {string} expectedHarness - Harness the leg scanned for.
76| * @returns {boolean} True when the id may be advertised for the harness.
77| ***/
78|function checkFleetIdForHarness(fleetId, expectedHarness) {
79|	if (typeof fleetId !== "string" || !fleetId.trim()) return false;
80|	const parsed = parseModelKey(fleetId.trim());
81|	if (!parsed || (parsed.form !== "harness" && parsed.form !== "harnessReasoning")) return false;
82|	if (expectedHarness && parsed.harness !== expectedHarness) return false;
83|	return true;
