239|/***
240| * MARK: runDiscoveryRound
241| * @description Runs the discovery legs for one harness list (a boot
242| *   seed, a cadence tick, or a Re-detect command) and combines the ids.
243| *   Legs run in list order, each independently watchdogged; harness ids
244| *   without a leg (`mock`, `custom`, unknown) are skipped, and blank
245| *   entries are dropped. Returns a plain object — the per-harness
246| *   slices stay readable via `getDiscoveryStatus()`.
247| * @example await runDiscoveryRound({ harnessIds: ['pi'] }) => { combinedIds: ['pi::mistral::x'], resultsByHarness: { pi: { harnessId: 'pi', ids: [...], error: null } } }
248| * @param {Object} [opts] - Labelled inputs.
249| * @param {string[]} [opts.harnessIds] - Harness ids to scan, in order.
250| * @param {number} [opts.timeoutMs] - Per-leg watchdog budget (ms).
251| * @param {Object} [opts.legOptions] - Seams forwarded to every leg (each leg gets a fresh copy).
252| * @returns {Promise<{combinedIds: string[], resultsByHarness: Object}>} Combined ids plus per-leg outcomes.
253| ***/
254|export async function runDiscoveryRound({ harnessIds = [], timeoutMs, legOptions = {} } = {}) {
255|	const effectiveTimeoutMs = resolveLegTimeoutMs(timeoutMs);
256|	const combinedIds = [];
257|	const resultsByHarness = {};
258|	for (const id of Array.isArray(harnessIds) ? harnessIds : []) {
259|		const clean = String(id ?? "").trim();
260|		if (!clean) continue;
261|		if (!Object.prototype.hasOwnProperty.call(DISCOVERY_LEGS, clean)) continue;
262|		const legResult = await runDiscoveryLeg(clean, { ...legOptions, timeoutMs: effectiveTimeoutMs });
263|		resultsByHarness[clean] = legResult;
264|		for (const modelId of legResult.ids) {
265|			if (!combinedIds.includes(modelId)) combinedIds.push(modelId);
266|		}
267|	}
268|	return { combinedIds, resultsByHarness };
269|}
