271|/***
272| * MARK: getDiscoveryStatus
273| * @description Reads the per-harness discovery status for heartbeat
274| *   facts: `{ [harnessId]: { ok, count, atMs, error? } }`. Pass the
275| *   configured harness ids to filter out stale slices from harnesses no
276| *   longer configured (read-time filter, so concurrent rounds cannot
277| *   race a prune); omit it to read every slice (tests, debugging).
278| * @example getDiscoveryStatus(['pi']) => { pi: { ok: true, count: 1, atMs: 123 } }
279| * @param {string[]} [onlyHarnessIds] - Harness ids to include (all when omitted).
280| * @returns {Object} Status by harness id.
281| ***/
282|export function getDiscoveryStatus(onlyHarnessIds) {
283|	const wanted = Array.isArray(onlyHarnessIds)
284|		? new Set(onlyHarnessIds.map((id) => String(id ?? "").trim()).filter(Boolean))
285|		: null;
286|	const out = {};
287|	for (const [id, slice] of Object.entries(discoveryCache)) {
288|		if (wanted && !wanted.has(id)) continue;
289|		out[id] = {
290|			ok: slice?.error == null,
291|			count: Array.isArray(slice?.ids) ? slice.ids.length : 0,
292|			atMs: slice?.atMs ?? null,
293|			...(slice?.error ? { error: slice.error } : {}),
294|		};
295|	}
296|	return out;
297|}
