299|/***
300| * MARK: summarizeDiscoverySlices
301| * @description Summarizes the current slices for one harness list into
302| *   the log/ack shape: stable per-harness counts plus the first leg
303| *   error in list order. Harness ids without a leg are skipped (they
304| *   never scan), and ids never scanned read as `0` rather than vanishing
305| *   from the line.
306| * @example summarizeDiscoverySlices(['pi', 'muse']) => { countsText: 'pi:1, muse:0', firstError: null }
307| * @param {string[]} [harnessIds] - Configured harness ids, in order.
308| * @returns {{countsText: string, firstError: Object|null}} Counts line plus first leg error.
309| ***/
310|export function summarizeDiscoverySlices(harnessIds = []) {
311|	const legged = (Array.isArray(harnessIds) ? harnessIds : [])
312|		.map((id) => String(id ?? "").trim())
313|		.filter((id) => id && Object.prototype.hasOwnProperty.call(DISCOVERY_LEGS, id));
314|	const countsText = legged
315|		.map((id) => `${id}:${discoveryCache[id]?.ids?.length ?? 0}`)
316|		.join(", ");
317|	const firstError = legged
318|		.map((id) => discoveryCache[id]?.error)
319|		.find((error) => error && error.code) || null;
320|	return { countsText, firstError };
321|}
