352|/***
353| * MARK: describePiEmptyCatalogue
354| * @description Explains one empty pi catalogue for the status slot: the
355| *   offline auth summary (when the harness offers `modelAuthStatus`)
356| *   distinguishes "no provider login" from "logged in but nothing
357| *   yielded" from a failed availability refresh, so the operator sees
358| *   the fix instead of a bare zero. Never throws — an unreadable
359| *   summary degrades to the generic wording.
360| * @example describePiEmptyCatalogue({ error: null, providers: [] }).message => 'Pi reported no models ready to use (no provider login found).'
361| * @param {Object|null} [authSummary] - `modelAuthStatus()` result (or null when unknown).
362| * @returns {{code: string, message: string, hint: string}} Classified empty-catalogue failure.
363| ***/
364|function describePiEmptyCatalogue(authSummary) {
365|	const providers = Array.isArray(authSummary?.providers) ? authSummary.providers : null;
366|	const configuredCount = providers ? providers.filter((entry) => entry && entry.configured).length : null;
367|	const refreshError = typeof authSummary?.error === "string" && authSummary.error.trim()
368|		? authSummary.error.trim().slice(-200)
369|		: "";
370|	let message = "Pi reported no models ready to use.";
371|	if (configuredCount === 0) {
372|		message = "Pi reported no models ready to use (no provider login found).";
373|	} else if (typeof configuredCount === "number" && configuredCount > 0) {
374|		message = `Pi reported no models ready to use (${configuredCount} provider(s) logged in, but none yielded models).`;
375|	}
376|	if (refreshError) message += ` Availability refresh failed: ${refreshError}.`;
377|	return {
378|		code: "PI_MODELS_EMPTY",
379|		message,
380|		hint: "Log in to a provider in pi (its ~/.pi/agent auth), then re-run model re-detection.",
381|	};
382|}
