384|/***
385| * MARK: discoverPiModels
386| * @description Lists the pi models ready to use right now via the pi
387| *   SDK availability snapshot (only providers with valid credentials
388| *   appear — survey q2): no CLI, no keys read, ids already canonical
389| *   `pi::…` keys. An empty catalogue throws `PI_MODELS_EMPTY` (with the
390| *   login state in the message when the harness can report it) instead
391| *   of resolving a silent `[]` — a bare zero with `ok: true` reads as
392| *   healthy, while the truth is "nothing logged in", which the
393| *   operator must see as a warning.
394| * @example await discoverPiModels({}) => ['pi::mistral::codestral-2508']
395| * @example await discoverPiModels({}) // throws PI_MODELS_EMPTY when no provider is logged in
396| * @param {Object} [ctx] - Leg seams (`createHarness` test double).
397| * @returns {Promise<string[]>} Canonical pi model ids (never silently empty).
398| ***/
399|export async function discoverPiModels(ctx = {}) {
400|	const harness = await loadPiHarness(ctx);
401|	const models = await harness.listModels({ refresh: true });
402|	const ids = dedupeStrings((models || []).map((m) => (typeof m === "string" ? m : m?.key)));
403|	if (ids.length > 0) return ids;
404|	let authSummary = null;
405|	if (harness && typeof harness.modelAuthStatus === "function") {
406|		try {
407|			authSummary = await harness.modelAuthStatus();
408|		} catch {
409|			authSummary = null;
410|		}
411|	}
412|	const empty = describePiEmptyCatalogue(authSummary);
413|	throwLegError(empty.code, empty.message, empty.hint);
414|}
