41|/***
42| * MARK: dedupeStrings
43| * @description Trims a raw leg result into a deduped id list, dropping
44| *   blanks and non-strings. Legs disagree on hygiene (some pass SDK rows
45| *   straight through), so every leg result funnels through here before
46| *   grammar validation.
47| * @example dedupeStrings([' a ', 'a', 42, '']) => ['a']
48| * @param {Array} [list] - Raw leg result (any mix of values).
49| * @returns {string[]} Clean unique ids.
50| ***/
51|function dedupeStrings(list) {
52|	const out = [];
53|	const seen = new Set();
54|	for (const item of list || []) {
55|		if (typeof item !== "string") continue;
56|		const value = item.trim();
57|		if (!value || seen.has(value)) continue;
58|		seen.add(value);
59|		out.push(value);
60|	}
61|	return out;
62|}
