86|/***
87| * MARK: resolveLegTimeoutMs
88| * @description Settles the watchdog budget for one leg run: a finite
89| *   positive override wins, anything else (missing, zero, negative,
90| *   NaN) falls back to the default. A non-positive budget would time
91| *   out a healthy leg on arrival, so it reads as "no override" rather
92| *   than "no time".
93| * @example resolveLegTimeoutMs(50) => 50
94| * @example resolveLegTimeoutMs(0) => 20000
95| * @param {unknown} rawTimeoutMs - Requested budget (ms).
96| * @returns {number} Effective budget (ms).
97| ***/
98|function resolveLegTimeoutMs(rawTimeoutMs) {
99|	return Number.isFinite(rawTimeoutMs) && rawTimeoutMs > 0
100|		? rawTimeoutMs
101|		: DISCOVER_LEG_TIMEOUT_DEFAULT_MS;
102|}
