104|/***
105| * MARK: awaitWithTimeout
106| * @description Awaits one leg promise behind a watchdog: the first of
107| *   the leg result and a timeout rejection wins, and the timer is always
108| *   cleared and unref'd so a hung leg can neither stall the round nor
109| *   pin the event loop. A late leg result after the timeout is ignored.
110| * @example await awaitWithTimeout(Promise.resolve(['a']), 50) => ['a']
111| * @param {Promise} promise - In-flight leg work.
112| * @param {number} timeoutMs - Watchdog budget (ms).
113| * @returns {Promise} The leg result, or a timeout rejection.
114| ***/
115|function awaitWithTimeout(promise, timeoutMs) {
116|	let timer = null;
117|	const timeoutPromise = new Promise((_, reject) => {
118|		timer = setTimeout(() => reject(new Error(`discovery timed out after ${timeoutMs}ms`)), timeoutMs);
119|		if (typeof timer.unref === "function") timer.unref();
120|	});
121|	return Promise.race([promise, timeoutPromise]).finally(() => {
122|		if (timer) clearTimeout(timer);
123|	});
124|}
