126|/***
127| * MARK: classifyLegError
128| * @description Sorts one leg failure into the status slot's stable
129| *   `{code,message,hint}` shape. Classified errors thrown by legs (the
130| *   agy/vibe catalogues' retained discovery failures, the honest-empty
131| *   legs' reasons) pass through untouched so the slot names the real
132| *   cause; anything else becomes `<HARNESS>_DISCOVERY_FAILED` with the
133| *   raw message attached. All strings are length-capped so one chatty
134| *   CLI cannot bloat every heartbeat.
135| * @example classifyLegError(Object.assign(new Error('no agy'), { code: 'AGY_BIN_MISSING', hint: 'install' }), 'antigravity') => { code: 'AGY_BIN_MISSING', message: 'no agy', hint: 'install' }
136| * @param {unknown} error - Whatever the leg threw.
137| * @param {string} harnessId - Harness the leg scanned for.
138| * @returns {{code: string, message: string, hint: string}} Status-slot error.
139| ***/
140|function classifyLegError(error, harnessId) {
141|	if (error && typeof error === "object" && typeof error.code === "string" && error.code.trim()) {
142|		return {
143|			code: error.code.trim().slice(0, 120),
144|			message: String(error.message || error.code).slice(0, 500),
145|			hint: typeof error.hint === "string" ? error.hint.slice(0, 500) : "",
146|		};
147|	}
148|	const detail = String(error?.message || error || "unknown error");
149|	return {
150|		code: `${String(harnessId || "harness").toUpperCase()}_DISCOVERY_FAILED`,
151|		message: detail.slice(0, 500),
152|		hint: `Re-run model re-detection after fixing the ${harnessId} setup.`,
153|	};
154|}
155|
156|/***
157| * MARK: throwLegError
158| * @description Throws a classified leg error: the honest-empty legs and
159| *   the retained catalogue failures raise through here so `runDiscoveryLeg`
160| *   catches a coded reason into the status slot instead of a bare Error.
161| * @example throwLegError('CODEX_DISCOVERY_UNAVAILABLE', 'no live transport', 'wait for the transport')
162| * @param {string} code - Stable status-slot code.
163| * @param {string} message - Human-readable cause.
164| * @param {string} [hint] - Operator fix, shown in Settings.
165| ***/
166|function throwLegError(code, message, hint = "") {
167|	const err = new Error(message);
168|	err.code = code;
169|	err.hint = hint;
170|	throw err;
171|}
