43|			message: `The muse CLI was not found ('${attemptedBinary}' is not runnable).`,
44|			hint: "Install the Muse CLI and ensure it is on PATH or in ~/.local/bin, or set KAINBAIN_MUSE_BIN to its absolute path.",
45|		};
