65|/***
66| * MARK: discoverClaudeModels
67| * @description Lists the models the installed `muse` CLI can serve, by
68| *   asking it over its own MSP wire protocol (`muse serve` stdio):
69| *   `initialize` → `initialized` → `model/list` (no session needed). Uses
70| *   the box's own login, so the runner never reads keys or calls provider
71| *   billing APIs — only model ids come back. Rows map to the fleet id
72| *   grammar `muse::<providerId>::<modelId>` (e.g.
73| *   `muse::meta::muse-spark-1.3`); malformed rows are skipped, ids deduped.
74| *   Lenient by default: any failure (missing CLI, timeout, unparsable
75| *   output) resolves to `[]`, never throws, so discovery can never break
76| *   boot. Strict mode (`strict: true`, used by the discovery leg) throws
77| *   the same classified `MUSE_MSP_*` failures the backend catalogue
78| *   reports, so an empty scan lands a named cause in Settings instead of
79| *   a silent zero. A CLI that answers `model/list` with zero rows still
80| *   resolves to `[]` in both modes — the leg reports that as
81| *   `MUSE_MSP_MODELS_EMPTY`.
82| * @example await discoverClaudeModels() => ['muse::meta::muse-spark-1.3']
83| * @example await discoverClaudeModels({ strict: true }) // throws MUSE_MSP_BIN_MISSING when the CLI is missing
84| * @param {Object} [opts]
85| * @param {string} [opts.bin='muse'] - CLI binary to spawn.
86| * @param {number} [opts.timeoutMs=20000] - Whole round-trip budget.
87| * @param {Function} [opts.spawnSyncFn=spawnSync] - Test seam.
88| * @param {boolean} [opts.strict=false] - Throw classified failures instead of resolving `[]`.
89| * @returns {Promise<string[]>} Discovered catalogue ids (possibly empty).
90| ***/
91|export async function discoverClaudeModels({ bin = "muse", timeoutMs = 20000, spawnSyncFn = spawnSync, strict = false } = {}) {
92|	const messages = [
93|		{ jsonrpc: "2.0", id: 1, method: "initialize", params: { clientInfo: { name: "kainbain", version: "0.1.0" } } },
94|		{ jsonrpc: "2.0", method: "initialized", params: {} },
95|		{ jsonrpc: "2.0", id: 2, method: "model/list", params: {} },
96|	].map((m) => `${JSON.stringify(m)}\n`).join("");
97|	let res;
98|	try {
99|		res = spawnSyncFn(bin, ["serve", "--no-session-log"], { input: messages, timeout: timeoutMs, encoding: "utf8" });
100|	} catch (spawnError) {
101|		if (!strict) return [];
102|		const classified = describeMuseSpawnFailure({ spawnError, bin });
103|		throwClassifiedMuseProbeFailure(classified.code, classified.message, classified.hint);
104|	}
105|	if (!res || res.error || typeof res.stdout !== "string") {
106|		if (!strict) return [];
107|		const classified = describeMuseSpawnFailure({ spawnError: res?.error, spawnResult: res, bin });
108|		throwClassifiedMuseProbeFailure(classified.code, classified.message, classified.hint);
109|	}
110|	const ids = [];
111|	let answeredModelList = false;
112|	let reportedServeError = "";
113|	for (const line of res.stdout.split("\n")) {
114|		const text = line.trim();
115|		if (!text.startsWith("{")) continue;
116|		let msg;
117|		try {
118|			msg = JSON.parse(text);
119|		} catch {
120|			continue;
121|		}
122|		if (msg && typeof msg === "object" && msg.error && !reportedServeError) {
123|			const serveDetail = String(msg.error?.message || msg.error?.code || "").trim().slice(-300);
124|			if (serveDetail) reportedServeError = serveDetail;
125|		}
126|		const rows = msg?.result?.models;
127|		if (!Array.isArray(rows)) continue;
128|		answeredModelList = true;
129|		for (const row of rows) {
130|			const provider = typeof row?.providerId === "string" ? row.providerId.trim() : "";
131|			const model = typeof row?.modelId === "string" ? row.modelId.trim() : "";
132|			if (!provider || !model || provider.includes(":") || model.includes(":")) continue;
133|			const id = `muse::${provider}::${model}`;
134|			if (!ids.includes(id)) ids.push(id);
135|		}
136|	}
137|	// The CLI ran but never answered model/list (old CLI without the
138|	// method, crashed host, foreign stdout): lenient callers read that as
139|	// "nothing usable", strict callers get the named failure.
140|	if (!answeredModelList && strict) {
141|		const reported = reportedServeError ? ` The host reported: ${reportedServeError}.` : "";
142|		throwClassifiedMuseProbeFailure(
143|			"MUSE_MSP_DISCOVERY_FAILED",
144|			`The muse CLI ran but did not answer model/list.${reported}`,
145|			"Check the muse version supports 'muse serve', or run 'muse serve --provider echo' by hand to see the full error.",
146|		);
147|	}
148|	return ids;
149|}
