151|/***
152| * MARK: resolveAdvertisedModels
153| * @description Picks the model list a heartbeat advertises. Default is
154| *   pin-wins (upgrade-safe): the operator's explicit `config.models`
155| *   wins when non-empty, then the singular `config.model`; the
156| *   discovery cache only fills in when nothing is pinned. Opt in to
157| *   discovery-wins with `config.modelDiscoveryWins` (env
158| *   `KAINBAIN_RUNNER_MODEL_DISCOVERY_WINS=1`, survey q4): a non-empty
159| *   discovery cache then replaces the pin, and the pin only fills in
160| *   when discovery yielded nothing yet. Empty everywhere means unpinned
161| *   (matches model-less tasks only) — never invents a capability.
162| * @example resolveAdvertisedModels({ models: ['a'] }, ['b']) => ['a']
163| * @example resolveAdvertisedModels({ models: ['a'], modelDiscoveryWins: true }, ['b']) => ['b']
164| * @param {Object} [config] - Runner config (`models` array / `model` / `modelDiscoveryWins`).
165| * @param {string[]} [discovered] - Last discovery result.
166| * @returns {string[]} Advertised model ids.
167| ***/
168|export function resolveAdvertisedModels(config, discovered) {
169|	const discoveredIds = Array.isArray(discovered) ? [...discovered] : [];
170|	const pinnedModels = Array.isArray(config?.models) && config.models.length > 0 ? [...config.models] : null;
171|	const pinnedModel = typeof config?.model === "string" && config.model.trim() ? [config.model.trim()] : null;
