1|/***
2| * MARK: modelAliases (shared alias grammar)
3| * @description THE single implementation of the KainBain per-project model
4| *   alias system, shared verbatim by the backend engine (`api/projectStore.js`,
5| *   `api/agentRunner.js`, `api/sessionStore.js`) and the frontend settings UI
6| *   (`frontend/src/components/settings/ModelAliasesSection.jsx`) so validation
7| *   and resolution rules cannot drift. Plain ESM, zero dependencies.
8| *
9| *   An alias binds a short per-project name (e.g. `small`, `design`) to one
10| *   or more weighted harness + model targets
11| *   (`{ name, targets: [{ harness, model, percent }] }`, persisted on
12| *   `project.modelAliases`; a legacy `{ name, harness, model }` record reads
13| *   as one 100% target). Stages reference aliases through the
14| *   existing harness-first fields — `harness: "alias"` + `model: "<name>"` —
15| *   so every inherit/override path keeps working unchanged, and editing an
16| *   alias changes every referencing stage with no stage edits (stages store
17| *   the reference, never a copy of the concrete values).
18| *
19| *   `alias` is a VIRTUAL harness id: it never names a real AgentHarness
20| *   (registering it throws — see `api/agent/harnessRegistry.js`), and an
21| *   alias target pointing back at `alias` is a loop, treated as unknown.
22| ***/
23|
24|/** The virtual harness id that scopes alias references. Never a real harness. */
25|export const ALIAS_HARNESS_ID = "alias";
26|
27|/** Alias names mirror the harness-id shape: lowercase, URL-safe. */
28|export const ALIAS_NAME_PATTERN = /^[a-z0-9][a-z0-9_-]*$/;
29|
30|/** Maximum alias name length (keeps picker labels and logs readable). */
31|export const ALIAS_NAME_MAX_LENGTH = 64;
32|
33|/***
34| * MARK: normalizeAliasName
35| * @description Trims an alias name to its usable form ("" when blank or
36| *   non-string, i.e. "no alias named").
37| * @example normalizeAliasName("  Small  ") => "Small"
38| * @example normalizeAliasName("") => ""
39| * @param {unknown} name - Raw alias name.
40| * @returns {string} Trimmed name, or "" when unset.
41| ***/
42|export function normalizeAliasName(name) {
43|	return typeof name === "string" ? name.trim() : "";
44|}
