46|/***
47| * MARK: validateAliasName
48| * @description Validates an alias name, returning an error string or null.
49| *   Names are trimmed, 1–64 chars, and must match `[a-z0-9][a-z0-9_-]*`
50| *   (case-sensitive: `Small` and `small` are different aliases, and uppercase
51| *   is rejected so references cannot drift by case).
52| * @example validateAliasName("small") => null
53| * @example validateAliasName("Small") => "…"
54| * @param {unknown} name - Raw alias name.
55| * @returns {string|null} Error message, or null when valid.
56| ***/
57|export function validateAliasName(name) {
58|	const trimmed = normalizeAliasName(name);
59|	if (!trimmed) return "Alias name is required";
60|	if (trimmed.length > ALIAS_NAME_MAX_LENGTH) {
61|		return `Alias name must be at most ${ALIAS_NAME_MAX_LENGTH} characters`;
62|	}
63|	if (!ALIAS_NAME_PATTERN.test(trimmed)) {
64|		return "Alias name must start with a letter or digit and contain only lowercase letters, digits, - and _";
65|	}
