69|/***
70| * MARK: validateAliasTarget
71| * @description Validates ONE weighted target inside a multi-target alias,
72| *   returning an error string or null. The target harness must be a
73| *   non-empty string that is NOT the virtual `alias` id (loop guard). The
74| *   target model is a string in any accepted model-key form (blank is
75| *   allowed at the grammar level for self-managed `none` harnesses — the
76| *   settings UI additionally requires a model for `list` harnesses). The
77| *   percent is an integer 1–100 (the rows of one alias must sum to exactly
78| *   100 — see `validateAliasTargets`).
79| * @example validateAliasTarget({ harness: "pi", model: "google::m", percent: 90 }, "small") => null
80| * @example validateAliasTarget({ harness: "pi", model: "m", percent: 0 }, "small") => "…"
81| * @param {unknown} target - Candidate `{ harness, model, percent }` record.
82| * @param {unknown} aliasName - Owning alias name (for error messages).
83| * @returns {string|null} Error message, or null when valid.
84| ***/
85|export function validateAliasTarget(target, aliasName) {
86|	const label =
87|		normalizeAliasName(aliasName) || "(unnamed alias)";
88|	if (!target || typeof target !== "object" || Array.isArray(target)) {
89|		return `Alias "${label}" has a target that must be an object { harness, model, percent }`;
90|	}
91|	const harness =
92|		typeof target.harness === "string" ? target.harness.trim() : "";
93|	if (!harness) return `Alias "${label}" has a target without a harness`;
94|	if (harness === ALIAS_HARNESS_ID) {
95|		return `Alias "${label}" cannot target the "${ALIAS_HARNESS_ID}" harness (aliases cannot point at aliases)`;
96|	}
97|	if (typeof target.model !== "string") {
98|		return `Alias "${label}" has a target without a model`;
99|	}
100|	if (
101|		typeof target.percent !== "number" ||
102|		!Number.isInteger(target.percent) ||
103|		target.percent < 1 ||
104|		target.percent > 100
105|	) {
106|		return `Alias "${label}" has a target whose percent must be a whole number from 1 to 100`;
107|	}
