111|/***
112| * MARK: validateAliasTargets
113| * @description Validates a whole multi-target split: a non-empty array whose
114| *   every target satisfies `validateAliasTarget` and whose percents sum to
115| *   exactly 100 (users see percentages, never arbitrary weights).
116| * @example validateAliasTargets([{ harness: "pi", model: "m", percent: 90 }, { harness: "custom", model: "", percent: 10 }], "small") => null
117| * @param {unknown} targets - Candidate targets array.
118| * @param {unknown} aliasName - Owning alias name (for error messages).
119| * @returns {string|null} Error message, or null when valid.
120| ***/
121|export function validateAliasTargets(targets, aliasName) {
122|	const label =
123|		normalizeAliasName(aliasName) || "(unnamed alias)";
124|	if (!Array.isArray(targets) || targets.length === 0) {
125|		return `Alias "${label}" needs at least one target`;
126|	}
127|	for (const target of targets) {
128|		const reason = validateAliasTarget(target, aliasName);
129|		if (reason) return reason;
130|	}
131|	const total = targets.reduce((sum, t) => sum + t.percent, 0);
132|	if (total !== 100) {
133|		return `Alias "${label}" splits ${total}% — Percents must add up to 100%`;
134|	}
135|	return null;
