149| * @example validateModelAlias({ name: "c", harness: "custom", model: "" }) => null
150| * @param {unknown} entry - Candidate alias record.
151| * @returns {string|null} Error message, or null when valid.
152| ***/
153|export function validateModelAlias(entry) {
154|	if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
155|		return "Alias must be an object { name, targets }";
156|	}
157|	const nameError = validateAliasName(entry.name);
158|	if (nameError) return nameError;
