280|/***
281| * MARK: selectWeightedIndex
282| * @description ONE deterministic step of smooth weighted round-robin: adds
283| *   each weight to its running score, picks the highest scorer (lowest
284| *   index wins ties), then subtracts the weight total from the winner so
285| *   the next pick rotates. With weights [90, 10] the minority index wins
286| *   exactly every 10th call, evenly spread — no random clustering, and the
287| *   sequence replays exactly from a zeroed score array (scores are kept
288| *   outside so the caller owns persistence: in-memory counters in
289| *   `api/aliasSelector.js`, injectable arrays in tests).
290| * @example selectWeightedIndex([90, 10], [0, 0]) => 0
291| * @param {Array<number>} weights - Per-target weights (the integer percents).
292| * @param {Array<number>} scores - Running scores, mutated in place (must match weights in length).
293| * @returns {number} Winning index (-1 when there is nothing to pick).
294| ***/
295|export function selectWeightedIndex(weights, scores) {
296|	if (!Array.isArray(weights) || weights.length === 0) return -1;
297|	const total = weights.reduce(
298|		(sum, w) => sum + (typeof w === "number" && w > 0 ? w : 0),
299|		0,
300|	);
301|	if (total <= 0) return -1;
302|	let winner = 0;
303|	let best = -Infinity;
304|	for (let i = 0; i < weights.length; i++) {
305|		const weight = typeof weights[i] === "number" && weights[i] > 0 ? weights[i] : 0;
306|		scores[i] = (typeof scores[i] === "number" ? scores[i] : 0) + weight;
307|		if (scores[i] > best) {
308|			best = scores[i];
309|			winner = i;
310|		}
311|	}
312|	scores[winner] -= total;
