316|/***
317| * MARK: normalizeModelAliases
318| * @description Normalizes a persisted alias list on write: drops non-objects
319| *   and invalid entries, trims every field, upgrades legacy single-target
320| *   records to the weighted form, dedupes by name (first wins), and returns
321| *   fresh canonical records. Every record carries `targets`
322| *   (`[{ harness, model, percent }]`, percents summing to 100) with the
323| *   first target mirrored onto the legacy `harness`/`model` fields, so a
324| *   rollback build that only reads the legacy fields keeps serving the top
325| *   target. Never throws — garbage in stored JSON degrades to fewer
326| *   aliases, not a broken project.
327| * @example normalizeModelAliases([{ name: " s ", harness: "pi", model: "m", extra: 1 }]) => [{ name: "s", harness: "pi", model: "m", targets: [{ harness: "pi", model: "m", percent: 100 }] }]
328| * @param {unknown} list - Persisted `project.modelAliases` value.
329| * @returns {Array<{name: string, harness: string, model: string, targets: Array}>} Clean alias records.
330| ***/
331|export function normalizeModelAliases(list) {
332|	if (!Array.isArray(list)) return [];
333|	const seen = new Set();
334|	const out = [];
335|	for (const entry of list) {
336|		if (validateModelAlias(entry)) continue;
337|		const name = normalizeAliasName(entry.name);
338|		if (seen.has(name)) continue;
339|		seen.add(name);
340|		const targets = getAliasTargets({
341|			harness:
342|				typeof entry.harness === "string" ? entry.harness.trim() : "",
343|			model: typeof entry.model === "string" ? entry.model : "",
344|			targets: Array.isArray(entry.targets)
345|				? entry.targets.map((t) =>
346|						t && typeof t === "object" && !Array.isArray(t)
347|							? {
348|									harness:
349|										typeof t.harness === "string" ? t.harness.trim() : "",
350|									model: typeof t.model === "string" ? t.model : "",
351|									percent: t.percent,
352|								}
353|							: t,
354|					)
355|				: undefined,
356|		});
357|		if (targets.length === 0) continue;
358|		out.push({
359|			name,
360|			harness: targets[0].harness,
361|			model: targets[0].model,
362|			targets: targets.map((t) => ({ ...t })),
