173|/***
174| * MARK: runDiscoveryLeg
175| * @description Runs one harness leg behind the watchdog and maintains
176| *   its cache slice. Success with usable ids replaces the slice;
177| *   failure, timeout, an unusable leg result, or an empty round keeps
178| *   the previous ids (survey q5: the old list stays until a better one
179| *   arrives) and records the error. Never throws — every failure lands
180| *   in the returned `{harnessId, ids, error}` and the slice, so one bad
181| *   harness cannot fail the round.
182| * @example await runDiscoveryLeg('pi', {}) => { harnessId: 'pi', ids: ['pi::mistral::x'], error: null }
183| * @param {string} harnessId - Harness to scan (a `DISCOVERY_LEGS` key).
184| * @param {Object} [ctx] - Leg seams (`timeoutMs`, harness/catalog overrides for tests).
185| * @returns {Promise<{harnessId: string, ids: string[], error: Object|null}>} Slice outcome.
186| ***/
187|export async function runDiscoveryLeg(harnessId, ctx = {}) {
188|	const leg = DISCOVERY_LEGS[harnessId];
189|	const previous = discoveryCache[harnessId];
190|	const previousIds = Array.isArray(previous?.ids) ? [...previous.ids] : [];
191|	const timeoutMs = resolveLegTimeoutMs(ctx?.timeoutMs);
192|
193|	if (typeof leg !== "function") {
194|		const error = { code: "NO_DISCOVERY_LEG", message: `No discovery leg for ${harnessId}`, hint: "" };
195|		discoveryCache[harnessId] = { ids: previousIds, atMs: Date.now(), error };
196|		return { harnessId, ids: [...previousIds], error };
197|	}
198|
199|	try {
200|		const raw = await awaitWithTimeout(leg(ctx), timeoutMs);
201|		if (!Array.isArray(raw)) {
202|			// A leg that resolves a non-list is broken (honest legs return
203|			// `[]` when there is nothing to serve): keep the old slice and
204|			// say so, instead of silently reading garbage as an empty menu.
205|			const error = {
206|				code: `${String(harnessId).toUpperCase()}_MODELS_UNPARSEABLE`,
207|				message: "Discovery returned an unusable result (expected a model id list).",
208|				hint: "",
209|			};
210|			discoveryCache[harnessId] = { ids: previousIds, atMs: Date.now(), error };
211|			return { harnessId, ids: [...previousIds], error };
212|		}
213|		const incoming = dedupeStrings(raw);
214|		// Keep only ids valid for this harness grammar.
215|		const valid = incoming.filter((id) => checkFleetIdForHarness(id, harnessId));
216|		if (valid.length > 0) {
217|			discoveryCache[harnessId] = { ids: valid, atMs: Date.now(), error: null };
218|			return { harnessId, ids: [...valid], error: null };
219|		}
220|		// Nothing usable: keep the previous slice. A round where every id
221|		// failed validation names that; a silently empty round (no login,
222|		// exec-only host) keeps whatever error the slice already had.
223|		const error = incoming.length > 0
224|			? {
225|				code: `${String(harnessId).toUpperCase()}_MODELS_UNPARSEABLE`,
226|				message: "Discovery yielded no usable model ids.",
227|				hint: "",
228|			}
229|			: (previous?.error || null);
230|		discoveryCache[harnessId] = { ids: previousIds, atMs: Date.now(), error };
231|		return { harnessId, ids: [...previousIds], error };
232|	} catch (err) {
233|		const error = classifyLegError(err, harnessId);
234|		discoveryCache[harnessId] = { ids: previousIds, atMs: Date.now(), error };
235|		return { harnessId, ids: [...previousIds], error };
236|	}
