255|	const effectiveTimeoutMs = resolveLegTimeoutMs(timeoutMs);
256|	const combinedIds = [];
257|	const resultsByHarness = {};
258|	for (const id of Array.isArray(harnessIds) ? harnessIds : []) {
259|		const clean = String(id ?? "").trim();
260|		if (!clean) continue;
261|		if (!Object.prototype.hasOwnProperty.call(DISCOVERY_LEGS, clean)) continue;
262|		const legResult = await runDiscoveryLeg(clean, { ...legOptions, timeoutMs: effectiveTimeoutMs });
263|		resultsByHarness[clean] = legResult;
