83|/***
84| * MARK: parseModelKey
85| * @description Parses any accepted model reference into its segments. Splits
86| *   on the first three `::` occurrences only, so ids that contain single `:`
87| *   (e.g. `pi::ollama-cloud::glm-5.3-flash:cloud::high`) survive intact, and
88| *   ids can never be truncated. Returns `{ form, ...segments }` or null when
89| *   the reference is structurally malformed (an empty non-final segment, or
90| *   five-plus segments) — callers treat null like an opaque string and never
91| *   throw, so arbitrary user input cannot crash resolution.
92| * @example parseModelKey('pi::ollama-cloud::glm-5.3-flash:cloud::high') => { form: 'harnessReasoning', harness: 'pi', provider: 'ollama-cloud', id: 'glm-5.3-flash:cloud', reasoning: 'high' }
93| * @example parseModelKey('pi::ollama-cloud::glm-5.3-flash:cloud') => { form: 'harness', harness: 'pi', provider: 'ollama-cloud', id: 'glm-5.3-flash:cloud' }
94| * @example parseModelKey('ollama-cloud::glm-5.3-flash:cloud') => { form: 'provider', provider: 'ollama-cloud', id: 'glm-5.3-flash:cloud' }
95| * @example parseModelKey('glm-5.3-flash:cloud') => { form: 'bare', id: 'glm-5.3-flash:cloud' }
96| * @example parseModelKey('p::i::extra::more::evenmore') => null (5 segments)
97| * @param {string|undefined} ref - Any model reference.
98| * @returns {Object|null} Parsed segments, or null when malformed.
99| ***/
100|export function parseModelKey(ref) {
101|	if (ref === undefined || ref === null) return null;
102|	const raw = String(ref);
103|	if (!raw) return null;
104|
105|	const first = raw.indexOf(MODEL_KEY_SEP);
106|	if (first === -1) {
107|		return { form: "bare", id: raw };
108|	}
109|
110|	const second = raw.indexOf(MODEL_KEY_SEP, first + MODEL_KEY_SEP.length);
111|	if (second === -1) {
112|		const provider = raw.slice(0, first);
113|		const id = raw.slice(first + MODEL_KEY_SEP.length);
114|		if (!provider || !id) return null;
115|		return { form: "provider", provider, id };
116|	}
117|
118|	const third = raw.indexOf(MODEL_KEY_SEP, second + MODEL_KEY_SEP.length);
119|	if (third === -1) {
120|		const harness = raw.slice(0, first);
121|		const provider = raw.slice(first + MODEL_KEY_SEP.length, second);
122|		const id = raw.slice(second + MODEL_KEY_SEP.length);
123|		if (!harness || !provider || !id || id.includes(MODEL_KEY_SEP)) return null;
124|		return { form: "harness", harness, provider, id };
125|	}
126|
127|	const harness = raw.slice(0, first);
128|	const provider = raw.slice(first + MODEL_KEY_SEP.length, second);
129|	const id = raw.slice(second + MODEL_KEY_SEP.length, third);
130|	const reasoning = raw.slice(third + MODEL_KEY_SEP.length);
131|	if (!harness || !provider || !id || !reasoning) return null;
132|	if (reasoning.includes(MODEL_KEY_SEP)) return null; // 5+ segments => malformed
133|	return { form: "harnessReasoning", harness, provider, id, reasoning };
