1|import { claimEligibleRunner, effectiveRunnerModels } from "./runnerMatches.js";
2|
3|/***
4| * MARK: fleetModelCatalog
5| * @description The fleet's dynamic model catalogue, derived live from Runner
6| *   registrations — never cached, so joins, leaves, heartbeat updates, and
7| *   operator allowlist edits reflect on the next read (graceful by
8| *   construction: there is no stale snapshot to invalidate).
9| *
10| *   One entry per distinct model id served by at least one claim-eligible
11| *   Runner (active status, not paused — the same gates dispatch applies
12| *   before per-task requirements). Deduped by exact id string: the same id
13| *   on two machines (e.g. muse spark through muse on both boxes) appears
14| *   once with `runnerCount: 2`.
15| *
16| *   - `harnesses`: union of the serving Runners' harness ids (any of them
17| *     can serve the id — dispatch gates harness and model independently).
18| *   - `tiers`: union of the serving Runners' tiers (effort levels).
19| *   - `runnerCount` / `runnerIds`: how many (and which) Runners serve it —
20| *     the availability signal pickers show instead of credential health.
21| * @example buildFleetModelCatalog([{ status: 'active', runnerId: 'r1', capabilities: { harnesses: [{ id: 'muse' }], models: ['m1'], tiers: ['T0'] } }])
22| *   => { models: [{ id: 'm1', harnesses: ['muse'], tiers: ['T0'], runnerCount: 1, runnerIds: ['r1'] }] }
23| * @param {Array<Object>} [runners=[]] - Registry records (`runners.list()`).
24| * @returns {{models: Array<Object>}} The catalogue (possibly empty, never null).
25| ***/
26|export function buildFleetModelCatalog(runners = []) {
27|	const byId = new Map(); // id -> { harnesses:Set, tiers:Set, runnerIds:Set }
28|	for (const record of Array.isArray(runners) ? runners : []) {
29|		if (!claimEligibleRunner(record)) continue;
30|		const runnerId = String(record?.runnerId ?? "").trim();
31|		if (!runnerId) continue;
32|		const caps =
33|			record?.capabilities && typeof record.capabilities === "object"
34|				? record.capabilities
35|				: {};
36|		const harnessIds = Array.isArray(caps.harnesses)
37|			? caps.harnesses
38|					.map((h) => (typeof h === "string" ? h.trim() : String(h?.id ?? "").trim()))
39|					.filter(Boolean)
40|			: [];
41|		const tiers = Array.isArray(caps.tiers)
42|			? caps.tiers.map((t) => String(t ?? "").trim()).filter(Boolean)
43|			: [];
44|		for (const raw of effectiveRunnerModels(record)) {
45|			const id = String(raw ?? "").trim();
46|			if (!id) continue;
47|			let entry = byId.get(id);
48|			if (!entry) {
49|				entry = { harnesses: new Set(), tiers: new Set(), runnerIds: new Set() };
50|				byId.set(id, entry);
51|			}
52|			for (const h of harnessIds) entry.harnesses.add(h);
53|			for (const t of tiers) entry.tiers.add(t);
54|			entry.runnerIds.add(runnerId);
55|		}
56|	}
57|	const models = [...byId.entries()].map(([id, entry]) => ({
58|		id,
59|		harnesses: [...entry.harnesses].sort(),
60|		tiers: [...entry.tiers].sort(),
61|		runnerCount: entry.runnerIds.size,
62|		runnerIds: [...entry.runnerIds].sort(),
63|	}));
64|	models.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
65|	return { models };
66|}

