            aria-label={percentLabel}
            type="number"
            min={1}
            max={100}
            step={1}
            value={target?.percent ?? ''}
            onChange={(e) => {
              const parsed = Number.parseInt(e.target.value, 10);
              onTargetChange({ percent: Number.isNaN(parsed) ? '' : parsed });
            }}
            disabled={disabled || single}
            title={
