315|/***
316| * MARK: validateDefaultModelCombination
317| * @description Validates a project's `defaultModel` against its effective
318| *   harness in the same two tiers. Blank/`"default"` always passes
319| *   (inherit). On the virtual `"alias"` harness the default names an alias:
320| *   an unresolvable name warns softly (never blocks — the alias may be
321| *   renamed later). On a concrete harness: a malformed non-blank ref is a
322| *   HARD error when it arrives in the save payload (stored values from a
323| *   harness change re-check warn softly instead, so unrelated saves are
324| *   never blocked by pre-existing data); a model on a self-managed `none`
325| *   harness warns softly (the stored value is ignored at dispatch); a model
326| *   absent from the harness's catalog right now warns softly.
327| * @example await validateDefaultModelCombination({ defaultModel: "a::b::c::d", harness: "pi", fromPayload: true }) => { error: "…malformed…", warnings: [] }
328| * @param {Object} [opts]
329| * @param {string} [opts.defaultModel] - The default model under validation.
330| * @param {string} [opts.harness] - The effective harness id (`""` = follow the server default).
331| * @param {boolean} [opts.fromPayload] - True when the ref arrives in this save's payload (stored re-checks warn softly).
332| * @param {Object} [deps]
333| * @param {Function} [deps.modelSelectionFor] - `(harnessId) => "none"|"list"` (defaults to the harness registry).
334| * @param {Function} [deps.modelIdsFor] - `(harnessId) => Promise<Set<string>|null>` catalog probe (defaults to `defaultModelIdsFor`).
335| * @param {Function} [deps.resolveAliasDefault] - `() => truthy when the project-default alias resolves` (peek; required for alias-harness checks).
336| * @param {Function} [deps.reasoningLevelsFor] - `(harnessId) => string[]|null` advertised levels (defaults to the harness registry).
337| * @returns {Promise<{error: string|null, warnings: string[]}>} The hard error and soft warnings.
338| ***/
339|export async function validateDefaultModelCombination(
340|	{ defaultModel, harness, fromPayload = false } = {},
341|	{
342|		modelSelectionFor = harnessModelSelection,
343|		modelIdsFor = defaultModelIdsFor,
344|		resolveAliasDefault = null,
345|		reasoningLevelsFor = harnessReasoningLevels,
346|	} = {},
347|) {
348|	const warnings = [];
349|	const model =
350|		typeof defaultModel === "string" ? defaultModel.trim() : "";
351|	if (!model || model === "default") return { error: null, warnings };
352|	const harnessId = typeof harness === "string" ? harness.trim() : "";
353|	if (harnessId === "alias") {
354|		// The default names an alias, not a model: grammar shape does not
355|		// apply — an unresolvable name warns softly, never blocks.
356|		let resolved = true;
357|		if (typeof resolveAliasDefault === "function") {
358|			try {
359|				resolved = Boolean(await resolveAliasDefault());
360|			} catch {
361|				resolved = true;
362|			}
363|		}
364|		if (!resolved) {
365|			warnings.push(
366|				`project default alias "${model}" does not resolve to any target — ` +
367|					`runs fall back to the built-in default. Fix it in Settings › Model Aliases.`,
368|			);
369|		}
370|		return { error: null, warnings };
371|	}
372|	if (harnessId && modelSelectionFor(harnessId) === "none") {
373|		warnings.push(
374|			`project harness "${harnessId}" manages its own model — the stored ` +
375|				`default model "${model}" is ignored at dispatch. Clear it in Settings.`,
376|		);
377|		return { error: null, warnings };
378|	}
379|	if (validateModelRefShape(model) === null) {
380|		const message =
381|			`project defaultModel "${model}" is a malformed model ref — use ` +
382|			`"harness::provider::id", "provider::id", or a bare id`;
383|		if (fromPayload) return { error: message, warnings };
384|		warnings.push(`${message} (stored value kept)`);
385|		return { error: null, warnings };
386|	}
387|	// Reasoning-level enforcement (hard on payload saves, soft on stored).
388|	const parsedDefault = parseModelKey(model);
389|	if (parsedDefault?.form === "harnessReasoning") {
390|		const level = parsedDefault.reasoning;
391|		const allowedHarnessId = harnessId || parsedDefault.harness;
392|		const advertised = reasoningLevelsFor(allowedHarnessId);
393|		const levelMessage =
394|			`project defaultModel "${model}" is not supported: ` +
395|			`reasoning level "${level}" is not supported by harness "${allowedHarnessId}"`;
396|		if (checkReasoningLevelText({ level })) {
397|			if (fromPayload) {
398|				return {
399|					error: `project defaultModel "${model}" is a malformed model ref — use "harness::provider::id", "provider::id", or a bare id`,
400|					warnings,
401|				};
402|			}
403|			warnings.push(
404|				`project defaultModel "${model}" is a malformed model ref — use "harness::provider::id", "provider::id", or a bare id (stored value kept)`,
405|			);
406|			return { error: null, warnings };
407|		}
408|		if (!Array.isArray(advertised)) {
409|			if (fromPayload) {
410|				return {
411|					error: `project defaultModel "${model}" carries reasoning level "${level}" but harness "${allowedHarnessId}" does not support adjustable reasoning`,
412|					warnings,
413|				};
414|			}
415|			warnings.push(
416|				`project defaultModel "${model}" carries reasoning level "${level}" but harness "${allowedHarnessId}" does not support adjustable reasoning (stored value kept)`,
417|			);
418|			return { error: null, warnings };
419|		}
420|		if (!advertised.includes(level)) {
421|			if (fromPayload) return { error: levelMessage, warnings };
422|			warnings.push(`${levelMessage} (stored value kept)`);
423|			return { error: null, warnings };
424|		}
425|	}
426|	if (modelSelectionFor(harnessId) !== "list") return { error: null, warnings };
427|	let ids = null;
428|	try {
429|		ids = await modelIdsFor(harnessId);
430|	} catch {
431|		ids = null;
432|	}
433|	if (!ids) return { error: null, warnings };
434|	if (!modelRefMatchesIds(model, ids)) {
435|		warnings.push(
436|			`project defaultModel "${model}" is not in the "${harnessId || "default"}" ` +
437|				`harness's model catalog right now — runs fall back at dispatch if it is ` +
438|				`still missing then`,
439|		);
440|	}
441|	return { error: null, warnings };
442|}
