444|/***
445| * MARK: sanitizeAliasTargetModels
446| * @description Blanks the model on every `none`-harness target of normalized
447| *   alias records (legacy load-path defense: rows saved before the API
448| *   refusal existed). List/unknown-harness targets pass through untouched.
449| *   Never mutates its input — returns fresh records with the legacy
450| *   `harness`/`model` mirror recomputed from the (possibly blanked) first
451| *   target — plus the list of dropped models for the one-line load warning.
452| * @example sanitizeAliasTargetModels([{ name: "w", harness: "muse", model: "g::m", targets: [{ harness: "muse", model: "g::m", percent: 100 }] }]).aliases => [{ name: "w", harness: "muse", model: "", targets: [{ harness: "muse", model: "", percent: 100 }] }]
453| * @param {Array} aliases - Normalized alias records.
454| * @param {Object} [opts]
455| * @param {Function} [opts.modelSelectionFor] - `(harnessId) => "none"|"list"` (defaults to the harness registry).
456| * @returns {{aliases: Array, dropped: Array<{alias: string, harness: string, model: string}>}} Clean records and the dropped models.
457| ***/
458|export function sanitizeAliasTargetModels(
459|	aliases,
460|	{ modelSelectionFor = harnessModelSelection } = {},
461|) {
462|	const list = Array.isArray(aliases) ? aliases : [];
463|	const dropped = [];
464|	const clean = list.map((entry) => {
465|		const name = normalizeAliasName(entry?.name);
466|		const targets = getAliasTargets(entry).map((target) => {
467|			const model =
468|				typeof target.model === "string" ? target.model.trim() : "";
469|			if (model && modelSelectionFor(target.harness) === "none") {
470|				dropped.push({ alias: name, harness: target.harness, model });
471|				return { ...target, model: "" };
472|			}
473|			return { ...target };
474|		});
475|		return {
476|			name,
477|			harness: targets[0]?.harness ?? "",
478|			model: targets[0]?.model ?? "",
479|			targets,
480|		};
481|	});
482|	return { aliases: clean, dropped };
483|}

