		if (ctx.home) dirs.push(path.join(ctx.home, ".pi", "agent", "bin"));
		const agentDir = ctx.env.PI_AGENT_DIR;
		if (typeof agentDir === "string" && agentDir.trim()) dirs.push(path.join(agentDir.trim(), "bin"));
